<script setup>
import{computed,onBeforeUnmount,onMounted,ref}from'vue';import{api}from'../api.js';import{apiErrorMessage}from'../stores/notifications.js';import{dataAge,formatDateTime}from'../utils/format.js';import AdminNav from'../components/AdminNav.vue';import SkeletonRows from'../components/SkeletonRows.vue'
const data=ref(null),loading=ref(true),error=ref(''),now=ref(Date.now());const freshness=computed(()=>{now.value;return dataAge(data.value?.checked_at)});let ticker
async function load(){loading.value=true;error.value='';try{data.value=(await api.get('/api/admin/settings')).data;now.value=Date.now()}catch(e){error.value=apiErrorMessage(e,'Не удалось проверить интеграции.')}finally{loading.value=false}}onMounted(()=>{load();ticker=setInterval(()=>now.value=Date.now(),15000)});onBeforeUnmount(()=>clearInterval(ticker))
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">АДМИНКА</p><h1>Discord и уведомления</h1><p class="muted">Состояние авторизации, webhook и внутреннего центра</p></div><div><span class="freshness">Проверено {{ freshness }}</span><button :disabled="loading" @click="load">Проверить</button></div></div><AdminNav/><p v-if="error" class="notice error">{{ error }} <button @click="load">Повторить</button></p><SkeletonRows v-if="loading" :rows="3"/><template v-else-if="data"><div class="integration-grid"><article class="panel"><i :class="data.discord.client_configured?'ok':'bad'"></i><div><strong>Discord OAuth</strong><p>{{ data.discord.client_configured?'Настроен':'Не заполнены client ID или secret' }}</p></div></article><article class="panel"><i :class="data.discord.webhook_configured?'ok':'bad'"></i><div><strong>Discord webhook</strong><p>{{ data.discord.webhook_configured?'Настроен':'Webhook не настроен, внешние сообщения не отправляются' }}</p></div></article><article class="panel"><i class="ok"></i><div><strong>Центр Armory</strong><p>{{ data.notifications.total }} уведомлений, {{ data.notifications.unread }} не прочитано</p><small>Последнее: {{ formatDateTime(data.notifications.last_created_at) }}</small></div></article></div><div class="panel settings-instruction"><h2>Какие события доставляются</h2><p>Заявки на привязку, аукционы, перебитые ставки, выплаты, нехватка золота и ближайшие активности. Напоминания зависят от ежеминутного запуска Laravel Scheduler.</p></div></template></section></template>
